#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply_op=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    // Place elements from right to left
    for(int target=n-1;target>=1;target--){
        // Find where target+1 is
        int j=-1;
        for(int k=0;k<=target;k++) if(p[k]==target+1){j=k;break;}
        if(j==target) continue;
        // Move p[j] to position target
        // First move to position 0: x=1, y=n-j -> need j>=1
        if(j>0){
            apply_op(1,n-j);
            // now target+1 is at position 0
        }
        // Now move position 0 to position target: x=n-target, y=target
        if(target>0){
            apply_op(n-target,target);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
